"""Build a local, self-contained findings page from measured CARLA evidence."""
import json
from pathlib import Path
import numpy as np
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'optimization_reports/visual_study'
data=json.loads((OUT/'measurements.json').read_text(encoding='utf-8'))
data['runs']+=json.loads((OUT/'measurements_clear.json').read_text(encoding='utf-8'))['runs']
labels={'original':'原始画面','clear':'清晰日光','daylight':'逆光日光试验','golden':'低角度日光','wet':'雨天试验','dusk':'暮色试验'}
order=['original','clear','golden','daylight','wet','dusk']
base=np.mean([r['fps'] for r in data['runs'] if r['preset']=='original'])
rows=''
for key in order:
    runs=[r for r in data['runs'] if r['preset']==key];fps=np.mean([r['fps'] for r in runs]);interval=np.mean([r['interval_p95_ms'] for r in runs])
    rows+=f'<tr><td>{labels[key]}</td><td>{runs[0]["fps"]:.2f} / {runs[1]["fps"]:.2f}</td><td><div class="bar" style="--w:{fps/1.2}%">{fps:.2f} FPS</div></td><td>{(fps/base-1)*100:+.2f}%</td><td>{interval:.2f} ms</td></tr>'
a=np.array(Image.open(OUT/'road_dry.png')).astype(float);b=np.array(Image.open(OUT/'road_wet.png')).astype(float)
roi=(slice(750,1050),slice(700,1200));mae=np.abs(a[roi]-b[roi]).mean()
options=''.join(f'<option value="{key}" {"selected" if key=="clear" else ""}>{labels[key]}</option>' for key in order if key!='original')
gallery=''.join(f'<a href="{key}.png" target="_blank"><img loading="lazy" src="{key}.png" alt="{labels[key]}"><b>{labels[key]}</b><span>查看 1920 × 1080 原图 ↗</span></a>' for key in order)
validation=json.loads((OUT/'studio_validation.json').read_text(encoding='utf-8'))
rid=validation['run_id']
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>map10 · 光影与场景控制实测</title><style>
:root{color-scheme:light;--ink:#172b35;--muted:#5f7279;--green:#187d6e}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#f1f4f2;font:15px/1.8 'Segoe UI','Microsoft YaHei',sans-serif}nav{background:#152730;color:white;padding:16px 5vw;display:flex;justify-content:space-between}nav a{color:#a8e8d7}main{max-width:1240px;margin:auto;padding:35px 24px 60px}h1{font-size:40px;line-height:1.3;letter-spacing:-1px;max-width:900px}h2{font-size:25px;margin:0 0 16px}h3{font-size:19px}p{max-width:1000px}.eyebrow{letter-spacing:2px;color:var(--green);font-size:12px;font-weight:700}.lead{font-size:18px;color:#4c626a}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:25px 0}.card{padding:20px;background:white;border:1px solid #d8e3df;border-radius:12px}.card b{display:block;font-size:24px}.card span{color:var(--muted);font-size:13px}section{margin:40px 0;padding-top:25px;border-top:1px solid #d1ddd8}.controls{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:15px 0}select,button{font:inherit;border:1px solid #a9beb5;border-radius:6px;background:white;padding:7px 12px;color:var(--ink)}input[type=range]{accent-color:var(--green);flex:1;min-width:180px}.compare{position:relative;aspect-ratio:16/9;background:#16262d;overflow:hidden;border-radius:12px}.compare img{position:absolute;width:100%;height:100%;object-fit:contain}.compare .old{clip-path:inset(0 50% 0 0)}.divider{position:absolute;top:0;bottom:0;left:50%;border-left:2px solid white;pointer-events:none}.tag{position:absolute;bottom:18px;padding:4px 12px;border-radius:5px;background:#102631bb;color:white;z-index:2}.left{left:16px}.right{right:16px}.note{padding:16px 20px;background:#e4eee9;border-left:3px solid #498879;border-radius:4px;color:#314f4a}.warn{background:#f6ecdc;border-color:#ae8756}.muted{color:var(--muted);font-size:13px}table{width:100%;border-collapse:collapse;background:white;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:12px 15px;border-bottom:1px solid #e0e9e4}th{font-size:13px;color:var(--muted)}.bar{background:linear-gradient(to right,#cce8dd var(--w),transparent var(--w));padding:4px 8px;border-radius:4px;min-width:160px;font-weight:600}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.gallery a{background:white;border-radius:9px;overflow:hidden;color:var(--ink);text-decoration:none;border:1px solid #d8e2dd}.gallery img{width:100%;display:block}.gallery b,.gallery span{display:block;padding:7px 12px 0}.gallery span{font-size:11px;color:var(--muted);padding-bottom:10px}a{color:#187667}code{font-size:12px;background:#e6eae7;padding:3px 5px;border-radius:3px}ul{padding-left:23px}li{margin:9px 0}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:25px}svg{width:100%;background:white;border:1px solid #d8e2dd;border-radius:8px}footer{font-size:12px;color:var(--muted);margin-top:40px}@media(max-width:800px){h1{font-size:30px}.cards,.gallery{grid-template-columns:1fr 1fr}.twocol{grid-template-columns:1fr}table{font-size:12px}td,th{padding:8px}.bar{min-width:100px}main{padding:24px 16px}}
</style><nav><b>HYX / MAP10 FIELD NOTES</b><div><a href="/">打开场景编辑器</a> · <a href="guide.html">使用说明</a></div></nav><main><div class="eyebrow">2026.10.03 · 实际 CARLA 渲染与控制验证</div><h1>先改善层次，再处理材质。<br>场景编排已经可以在界面里完成。</h1><p class="lead">清晰日光能减少泛白、保留阴影，提升幅度有限。map10 的重复立面、路面反光和天气材质适配，是继续提高真实感的主要限制。下面保留有效方案和效果不佳的试验原图。</p>
<div class="cards"><div class="card"><b>6 组画面</b><span>固定机位、1080p 原始 RGB，无后期调色</span></div><div class="card"><b>约 104 FPS</b><span>单相机无采样限速；各方案差别很小</span></div><div class="card"><b>3D 布置 + 事件</b><span>实机运行、暂停、轨迹与清理已验证</span></div></div>
<section><h2>01 / 拖动看画面差别</h2><div class="controls"><label>右侧方案 <select id="preset">OPTIONS</select></label><input id="split" type="range" min="0" max="100" value="50" aria-label="原始与调整画面对比位置"></div><div class="compare"><img id="new" src="clear.png" alt="调整后的同机位画面"><img class="old" id="old" src="original.png" alt="原始画面"><div class="divider" id="divider"></div><span class="tag left">原始</span><span class="tag right" id="label">清晰日光</span></div><p class="note" id="observation"></p><p class="muted">太阳高度 45° / 方位 220° 保持原始方向；清晰日光将雾浓度从 2 降到 0.2、雾起始距离从 0.75 m 移到 150 m，并使用 −0.35 曝光补偿。精确参数见原始测量文件。真实感评价为图像观察，尚未做受试者盲评。</p></section>
<section><h2>02 / 渲染速度：画面变化没有明显额外开销</h2><table><thead><tr><th>方案</th><th>两轮 FPS</th><th>平均出帧</th><th>相对原始</th><th>P95 帧间隔</th></tr></thead><tbody>ROWS</tbody></table><p class="muted">方法：CARLA 0.9.15-dirty，map10，RTX 4080 SUPER；1920 × 1080、FOV 100、sensor_tick=0。每次预热 4 秒，再计时 12 秒；原始及四组试验采用正反顺序各一轮，清晰日光随后测两轮。回调只保留最新帧，计时后保存 PNG。UE 编辑器保持运行。这里统计收到的独立 RGB 帧，不是 GPU 单帧耗时，也不是浏览器 MJPEG 显示帧率。</p><p class="note">各方案约在 ±1% 范围，不能据此宣称光影设置带来显著加速。前次 5740 × 1010、多相机和 Pygame 显示测试的约 30.77 → 41.02 FPS 属于另一种负载，不能与本页 104 FPS 直接比较。<a href="http://127.0.0.1:8766/map10_comparison.html">查看前次优化对照</a>。</p><p><a href="measurements.json">下载五组原始数据</a> · <a href="measurements_clear.json">清晰日光数据</a> · <a href="restoration.json">天气与参与者恢复记录</a></p></section>
<section><h2>03 / 材质问题已定位，湿度滑块不能代替材质改造</h2><div class="twocol"><div><h3>从本机资产读到了什么</h3><p><code>Asphalt1_Road</code> 的导出图连接了 Diff → BaseColor、Spec → Specular、Norm → Normal，未见 Roughness 输入连接、天气集合或可命名的纹理参数。纹理 UV 缩放为 0.35。</p><p>当前 CARLA 的动态纹理替换代码按指定参数名查找输入，这种直接 TextureSample 材质不能靠传入新纹理就可靠替换。没有覆盖地图的原始材质资产。</p><p><a href="Asphalt1_Road.t3d">查看实际材质图导出</a> · <a href="materials.json">UE 只读参数检查</a></p></div><div><h3>控制变量实测</h3><p>保持相机、照明和雨量相同，只把湿润/积水从 0 改为 100。道路 ROI（x=700..1199，y=750..1049）的平均 RGB 绝对差为 <b>MAE / 255</b>，平均亮度几乎不变，未看到明显的湿路响应。</p><p>这支持“该路面没有接入天气湿润变化”，不是对所有地图材质的结论。轻微差值也可能来自时序抖动。</p><p><a href="road_dry.png">干燥原图</a> · <a href="road_wet.png">湿度 100 原图</a></p></div></div><h3>下一层画质提升应改哪里</h3><ul><li>路面：做参数化材质，将粗糙度、法线强度与干湿混合暴露出来；先在独立材质副本上测试，使用真实比例的细节和低频变化，避免全路均匀镜面感。</li><li>建筑：增加窗框深度、玻璃与墙面材质差异、表面细节和适量街边物件。光照调整无法补足这些几何细节。</li><li>灯光：当前项目配置关闭默认 AO 和 Bloom。是否启用 AO、接触阴影及调整反射需要单独 A/B 与性能测量，本次没有把未验证的 UE 全局配置改动混进结果。</li></ul><p class="muted">原理参考：粗糙度控制反射的集中程度，Specular 与 Roughness 是不同输入。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/physically-based-materials-in-unreal-engine">Epic：Physically Based Materials</a>。天气参数主要改变可见表现，不能用湿度替代摩擦设置。<a href="https://carla.readthedocs.io/en/0.9.15/python_api/#carla.WeatherParameters">CARLA WeatherParameters</a>。</p></section>
<section><h2>04 / 控车效果与前端编排</h2><p>已有 7 个原场景的可编辑模板，以及行人横穿示例。车辆可以设置初速度、加减速度、跟车反应时间、最小间距、横向偏移、变道、道路路线、灯光和制动；事件支持时间、位置、速度、距离及事件依赖。</p><div class="twocol"><div><h3>已完成的实机验证</h3><ul><li>25 秒组合场景执行了全部 10 个事件：跟车、灯光、偏移、生成、制动、恢复、移除、偏移恢复、变道、路线重规划。</li><li>变道返回成功；组合场景无碰撞。暂停时仿真计时与本次车辆位置保持，恢复后继续运动。</li><li>短时键盘控制切换回自动控制；停止后无本次车辆/传感器残留，天气恢复。</li><li>浏览器实际操作验证了拖动位置、点选路线、修改表单、另存、保存和实机预览。</li><li>44 项自动化测试通过；7 个原场景模板完成各 3 秒的生成/渲染/运动/清理检查。行人示例完整运行 25 秒，横穿后停在路线终点附近，无碰撞。</li></ul></div><div><h3>运行数据</h3><p><a href="/api/runs/RUNID/telemetry.csv">下载逐车轨迹 / 速度 CSV</a><br><a href="/api/runs/RUNID/events.json">动作与变道结果 JSON</a><br><a href="studio_validation.json">组合场景验收记录</a><br><a href="template_smoke.json">8 个模板实测记录</a></p><p class="note warn">模板保留布置和目标参数，但新引擎以条件事件编排，变道异步执行，TOR 当前是标记而非提示音；不能把它当成原实验试次的轨迹或接管时序等价替代。正式实验前仍应按具体危险场景复核。</p></div></div><h3>组合验证：实际速度曲线</h3><svg id="chart" viewBox="0 0 1000 250" role="img" aria-label="组合场景中主车和前车的实际速度曲线"></svg><p class="muted">纵轴 km/h；横轴仿真秒。5 秒时前车制动，7 秒恢复目标速度；主车根据前车状态调整。</p><p><a href="/">进入场景编辑器 →</a> · <a href="guide.html">操作指南</a></p></section>
<section><h2>05 / 全部试验原图</h2><div class="gallery">GALLERY</div><p class="muted">雨天方案出现“暗天空、亮地面”的不协调效果，保留为失败样例；低太阳高度的暮色在此地图中明显过暗。它们作为编辑器试验预设提供，不推荐直接用于正式视觉刺激。</p></section><footer>所有画面来自本机 map10 的真实 CARLA RGB 传感器。没有 AI 生成或后期增强。研究结果只覆盖当前地图、机位和机器；控制验收不证明任意用户新建场景都不会碰撞。</footer></main><script>
const labels=LABELS,notes={clear:'建议从清晰日光开始：减少雾气与泛白，保留原来的阴影结构。改善是渐进的，重复立面和材质细节仍然明显。',daylight:'逆光放大了路面高光和法线细节，看起来偏亮、偏滑。此机位下不优于清晰日光。',golden:'低角度日光让色调偏暖，阴影区域更稳定，可作为日落场景；不能单凭暖色判定更真实。',wet:'失败样例：天空明显变黑，但地面仍然明亮；路面也未表现出与湿度对应的可靠变化。需要先修天空/材质适配。',dusk:'当前环境照明不足，画面很暗；编辑器会开启本次车辆近光灯，但这张静态对照未开启车灯，仍不能代表完成夜景适配。'};
const preset=document.getElementById('preset'),split=document.getElementById('split');function show(){document.getElementById('new').src=preset.value+'.png';document.getElementById('label').textContent=labels[preset.value];document.getElementById('observation').textContent=notes[preset.value]}preset.onchange=show;split.oninput=()=>{document.getElementById('old').style.clipPath=`inset(0 ${100-split.value}% 0 0)`;document.getElementById('divider').style.left=split.value+'%'};show();
const samples=SAMPLES,svg=document.getElementById('chart');let content='';for(let v=0;v<=40;v+=10){const y=215-v*4.5;content+=`<line x1="50" y1="${y}" x2="970" y2="${y}" stroke="#dce5e0"/><text x="18" y="${y+4}" fill="#647b72" font-size="12">${v}</text>`}for(let t=0;t<=25;t+=5)content+=`<text x="${50+t*36}" y="242" fill="#647b72" font-size="12">${t}s</text>`;for(const [id,color,name]of[['ego','#16806a','主车'],['lead','#c78336','前车']]){const points=samples.filter(s=>s.actors?.[id]).map(s=>`${50+s.elapsed*36},${215-s.actors[id].speed*4.5}`).join(' ');content+=`<polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.5"/><text x="${id==='ego'?730:835}" y="24" fill="${color}" font-size="14">━ ${name}</text>`}svg.innerHTML=content;
</script></html>'''
for k,v in {'OPTIONS':options,'ROWS':rows,'MAE':f'{mae:.3f}','RUNID':rid,'GALLERY':gallery,'LABELS':json.dumps(labels,ensure_ascii=False),'SAMPLES':json.dumps(validation['snapshots'])}.items():html=html.replace(k,v)
(OUT/'index.html').write_text(html,encoding='utf-8')
guide='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scene Studio 使用说明</title><style>body{font:16px/1.85 'Segoe UI','Microsoft YaHei',sans-serif;color:#203b43;background:#f1f5f2;max-width:1000px;margin:40px auto;padding:0 24px}h1{font-size:36px}h2{margin-top:35px}a{color:#187d6e}code{background:#dfeae4;padding:4px}li{margin:9px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #c7d7ce}</style><a href="/">← 场景编辑器</a> · <a href="index.html">研究与实测</a><h1>不用改 Python，布置和编排驾驶场景</h1><h2>启动</h2><ol><li>在 CARLA UE 编辑器中打开 map10 并进入运行状态。</li><li>双击项目目录的 <code>Start-SceneStudio.cmd</code>，保持服务窗口打开。</li><li>浏览器打开 <a href="http://127.0.0.1:8877/">http://127.0.0.1:8877/</a>。已有服务在运行时直接打开此地址。</li></ol><h2>新建一个场景</h2><ol><li>从场景库选择模板，点击“另存为”，给副本命名。也可以点击“新场景”从一辆主车开始。</li><li>选中参与者，用“移动”箭头或“旋转”圆环布置。左键操作控件，右键拖动平移地图，滚轮缩放；“俯视”方便对准车道。</li><li>“吸附车道”在移动结束时把位置和方向对齐最近的可驾驶车道。行人不自动吸附。关闭吸附可以设置路边、非车道位置；保存的初始高度必须在地面上方。</li><li>右侧填写模型、初始速度、加减速度、左偏移。普通交通会考虑前方车辆，实验车辆主要按设定动作行驶。勾选“启动即具有目标速度”是一种初始条件；取消后从静止物理加速。</li><li>点击“绘制路线”，依次点地图，点击“完成绘制”。车辆按道路网络连接路线点；行人按点移动。车辆到最后一点附近会制动。方向不连通的路线会报错。</li><li>添加事件，选择“何时发生”和“发生什么”。时间单位是仿真秒；相对事件的延时从该事件触发时开始计算，每个事件只触发一次。</li><li>保存。使用 Ctrl+Z / Ctrl+Y 撤销或重做编辑；导出与导入使用 JSON。</li></ol><h2>预览与运行</h2><table><tr><th>操作</th><th>作用</th></tr><tr><td>预览布置</td><td>生成静止参与者，显示 CARLA 真实 RGB。拖动已有参与者可以同步位置；新增、删除、换模型在下次预览生效。</td></tr><tr><td>光影 → 应用到实机预览</td><td>即时修改天气和相机外观，重新建立 RGB 相机。尺寸/FOV/采样 Hz 在下次启动时使用。</td></tr><tr><td>运行场景</td><td>按初始配置生成参与者并执行事件。修改的初始布置供下次运行使用；要在本次运行改变行为，在事件面板点“立即执行动作”。</td></tr><tr><td>暂停 / 继续</td><td>冻结本次参与者和本次场景计时。CARLA 世界和其他客户端仍会运行。</td></tr><tr><td>键盘接管 / 恢复自动</td><td>点击接管再把焦点放在实时画面上，W 油门、S 制动、A/D 转向。后台或失去输入 0.5 秒后自动制动。恢复自动后继续事件控制。</td></tr><tr><td>停止</td><td>清理本次创建的车辆、行人、传感器，恢复会话开始前天气；不删除其他客户端车辆。</td></tr><tr><td>运行记录</td><td>下载配置、逐车 CSV 和事件记录。保存场景时上一版本自动保留在 studio_data/history。</td></tr></table><h2>开始设置新场景的几种方式</h2><ul><li>前车急刹：设置前车在 5 秒触发制动，或让主车距前车小于指定距离时触发。</li><li>车辆切入：邻道车辆在指定坐标触发变道，可配置方向、车道数与纵向变道距离。变道会检查目标车道及附近车辆，失败结果记录在事件日志。</li><li>行人横穿：选择行人模型，设置行人运动与路线点，以时间或距离触发速度变化。</li><li>临时障碍：取消该参与者“初始生成”，用生成事件在适当时刻出现，后续事件可移除。主视角参与者必须初始生成。</li><li>跟车差异：编辑跟随目标、反应延时和最小间距。当前跟车时间间隔使用控制器默认值，界面没有提供任意车辆动力学参数编辑。</li></ul><h2>边界与使用习惯</h2><ul><li>这是本机单会话编辑器，要求 CARLA 异步模式；每次一个预览或运行。网页刷新后会继续显示现有会话，不会停止车辆。关闭浏览器前先点击停止；服务关闭前也先停止。</li><li>三维视图是基于真实道路拓扑的布置工具，车辆和建筑是简化表示；实际材质与光照以右侧 RGB 为准。未标注语义的导入建筑可能没有代理盒。</li><li>随机种子字段暂为配置保留字段，本编辑器没有随机交通生成器，不应把异步物理试次看作逐帧确定重放。</li><li>场景模板保留原脚本的位置、目标速度和条件，但 TOR 仅记录事件标记，不播放提示音、不连接原方向盘输入和多屏窗口。正式实验应验证接管提示和时序后使用。</li><li>湿度和雨量不自动改变轮胎摩擦；道路材质需支持天气才能显示湿润。雨天/暮色预设在 map10 上效果不佳，已在研究报告保留失败对照。</li><li>静止障碍物不创建车辆控制器，需要变速的车辆请使用实验车辆并设初始速度 0；路线、跟车、变道是物理控制目标，不保证无碰撞。</li></ul><h2>文件位置</h2><p>入口：<code>scene_studio/server.py</code>；每次运行是独立进程 <code>runner.py</code>。场景在 <code>studio_data/scenes</code>，运行数据在 <code>studio_data/runs</code>。前端所需 Three.js 已保存在本地，无须 CDN。</p><p>Python 依赖：项目原有 CARLA 0.9.15、numpy、pygame、networkx，以及 Flask、opencv-python。当前机器已安装并验证。原始 Scene*.py 继续可单独运行。</p></html>'''
(OUT/'guide.html').write_text(guide,encoding='utf-8')
print(OUT/'index.html')
